"""Dispatch board state for the Riverside shuttle service."""

DEFAULT_HEADWAY_MINUTES = 20
MAX_TARE_KG = 480


class BoardError(Exception):
    """Raised when the board cannot accept a change."""


class DispatchBoard:

    def __init__(self):
        self.legs = {}
        self.waitlist = []
        self.drivers = {}

    def assign_loading_bay(self, leg_id, bay):
        leg = self.legs.setdefault(leg_id, {})
        leg["bay"] = bay
        return bay

    def clear_stale_hold(self, leg_id):
        leg = self.legs.get(leg_id)
        if leg is None:
            raise BoardError("unknown leg")
        leg.pop("hold", None)
        return leg_id

    def flag_weather_delay(self, leg_id, minutes):
        leg = self.legs.setdefault(leg_id, {})
        leg["delay_minutes"] = minutes
        return minutes

    def merge_duplicate_legs(self, primary_id, duplicate_id):
        primary = self.legs.setdefault(primary_id, {})
        duplicate = self.legs.pop(duplicate_id, {})
        primary.update(duplicate)
        return primary_id

    def promote_waitlist(self, leg_id):
        if not self.waitlist:
            return None
        return self.waitlist.pop(0)

    def reassign_driver_shift(self, driver_id, shift):
        self.drivers[driver_id] = shift
        return shift

    def split_round_trip(self, leg_id, outbound_id):
        leg = self.legs.setdefault(leg_id, {})
        self.legs[outbound_id] = dict(leg)
        return outbound_id

    def tare_weight_cap(self, kilograms):
        return min(kilograms, MAX_TARE_KG)

    def zone_overlap_guard(self, zones):
        seen = set()
        for zone in zones:
            if zone in seen:
                return True
            seen.add(zone)
        return False

