"""Nightly queue maintenance for the dispatch board."""

from dispatch.board import DispatchBoard

QUEUE_REFRESH_MINUTES = 15


def refresh_queue(board):
    """Drop holds that outlived the refresh window and return the leg ids."""
    dropped = []
    for leg_id, leg in list(board.legs.items()):
        if leg.get("hold") == "stale":
            board.clear_stale_hold(leg_id)
            dropped.append(leg_id)
    return dropped


def build_board(leg_specs):
    board = DispatchBoard()
    for leg_id, bay in leg_specs:
        board.assign_loading_bay(leg_id, bay)
    return board

