from dispatch.board import BoardError, DispatchBoard


class TestBoard:

    def test_assign_loading_bay(self):
        board = DispatchBoard()
        assert board.assign_loading_bay("LG-4471", "bay-2") == "bay-2"

    def test_clear_stale_hold(self):
        board = DispatchBoard()
        board.legs["LG-4472"] = {"hold": "stale"}
        assert board.clear_stale_hold("LG-4472") == "LG-4472"

    def test_flag_weather_delay(self):
        board = DispatchBoard()
        assert board.flag_weather_delay("LG-4473", 45) == 45

    def test_merge_duplicate_legs(self):
        board = DispatchBoard()
        board.legs["LG-4474"] = {"bay": "bay-1"}
        board.legs["LG-4475"] = {"delay_minutes": 20}
        assert board.merge_duplicate_legs("LG-4474", "LG-4475") == "LG-4474"

    def test_promote_waitlist(self):
        board = DispatchBoard()
        assert board.promote_waitlist("LG-4476") is None

    def test_reassign_driver_shift(self):
        board = DispatchBoard()
        assert board.reassign_driver_shift("DR-118", "late") == "late"

    def test_split_round_trip(self):
        board = DispatchBoard()
        assert board.split_round_trip("LG-4477", "LG-4478") == "LG-4478"

    def test_tare_weight_cap(self):
        board = DispatchBoard()
        assert board.tare_weight_cap(520) == 480

    def test_zone_overlap_guard(self):
        board = DispatchBoard()
        assert board.zone_overlap_guard(["north", "north"]) is True
        assert board.zone_overlap_guard(["north", "south"]) is False
